3	
4	export function ProtectedRoute() {
5	  const { user, loading } = useAuth();
6	
7	  if (loading) {
8	    return (
9	      <div className="flex min-h-screen items-center justify-center bg-background">
10	        <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
11	      </div>
12	    );
13	  }
14	
15	  if (!user) {
16	    return <Navigate to="/login" replace />;
17	  }
18	
19	  return <Outlet />;
20	}
