1	import { useEffect } from "react";
2	import { useNavigate } from "react-router-dom";
3	import supabase from "@/lib/supabase";
4	
5	/**
6	 * Handles the OAuth / magic-link redirect from Supabase.
7	 * Supabase processes the URL hash automatically; we just wait
8	 * for the session to resolve and then forward the user.
9	 */
10	export default function AuthCallback() {
11	  const navigate = useNavigate();
12	
13	  useEffect(() => {
14	    supabase.auth.getSession().then(({ data: { session } }) => {
15	      if (session) {
16	        navigate("/dashboard", { replace: true });
17	      } else {
18	        navigate("/login", { replace: true });
19	      }
20	    });
21	  }, [navigate]);
22	
23	  return (
24	    <div className="flex min-h-screen items-center justify-center bg-background">
25	      <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
26	    </div>
27	  );
28	}
