7	// ── Derived types for dashboard ─────────────────────────────────
8	
9	export interface ScoreTrendPoint {
10	  week: string;
11	  score: number;
12	}
13	
14	export interface ScoreDistributionBucket {
15	  range: string;
16	  count: number;
17	  fill: string;
18	}
19	
20	export interface DashboardData {
21	  stats: DashboardStats;
22	  recentScans: Scan[];
23	  scoreTrend: ScoreTrendPoint[];
24	  scoreDistribution: ScoreDistributionBucket[];
25	  topQuickWins: (Finding & { pillar: string })[];
26	  latestScanId: string | null;
27	}
