import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Bot, ArrowLeft, Mail } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { useAuth } from "@/contexts/AuthContext";
import supabase from "@/lib/supabase";

const ForgotPassword = () => {
  const navigate = useNavigate();
  const { user, loading } = useAuth();

  const [email, setEmail] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [sent, setSent] = useState(false);

  // Redirect if already authenticated
  useEffect(() => {
    if (!loading && user) {
      navigate("/dashboard", { replace: true });
    }
  }, [user, loading, navigate]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!email.trim()) {
      toast.error("Email is required.");
      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      toast.error("Enter a valid email address.");
      return;
    }

    setSubmitting(true);

    const { error } = await supabase.auth.resetPasswordForEmail(email.trim(), {
      redirectTo: `${window.location.origin}/reset-password`,
    });

    setSubmitting(false);

    if (error) {
      toast.error(error.message ?? "Failed to send reset email. Please try again.");
      return;
    }

    setSent(true);
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-4">
      <div className="w-full max-w-sm">
        {/* Logo */}
        <Link to="/" className="mb-10 flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
            <Bot className="h-4 w-4 text-white" />
          </div>
          <span className="text-lg font-bold tracking-tight text-foreground">CROBOT</span>
        </Link>

        {sent ? (
          /* Success state */
          <div className="space-y-4">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/10">
              <Mail className="h-6 w-6 text-primary" />
            </div>
            <h1 className="text-2xl font-bold text-foreground">Check your email</h1>
            <p className="text-sm text-muted-foreground">
              We sent a password reset link to{" "}
              <span className="font-medium text-foreground">{email}</span>.
              The link expires in 1 hour.
            </p>
            <p className="text-xs text-muted-foreground">
              Didn't receive it? Check your spam folder or{" "}
              <button
                type="button"
                className="text-primary hover:underline"
                onClick={() => setSent(false)}
              >
                try a different email
              </button>
              .
            </p>
            <Button
              variant="outline"
              className="mt-2 w-full border-slate-200"
              onClick={() => navigate("/login")}
            >
              Back to login
            </Button>
          </div>
        ) : (
          /* Form state */
          <div className="space-y-4">
            <div>
              <h1 className="text-2xl font-bold text-foreground">Reset your password</h1>
              <p className="mt-1.5 text-sm text-muted-foreground">
                Enter your account email and we'll send you a reset link.
              </p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="fp-email">Email address</Label>
                <Input
                  id="fp-email"
                  type="email"
                  placeholder="you@company.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="border-slate-200"
                  required
                  disabled={submitting}
                  autoFocus
                />
              </div>

              <Button
                type="submit"
                className="w-full py-5 font-semibold"
                disabled={submitting}
              >
                {submitting ? (
                  <span className="flex items-center gap-2">
                    <span className="h-4 w-4 animate-spin rounded-full border-2 border-primary-foreground border-t-transparent" />
                    Sending…
                  </span>
                ) : (
                  "Send reset link"
                )}
              </Button>
            </form>

            <Link
              to="/login"
              className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors"
            >
              <ArrowLeft className="h-4 w-4" />
              Back to login
            </Link>
          </div>
        )}
      </div>
    </div>
  );
};

export default ForgotPassword;

import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Bot, Eye, EyeOff } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import supabase from "@/lib/supabase";

/**
 * Handles the password reset flow after the user clicks the email link.
 *
 * Supabase sends a PKCE code in the URL fragment (#access_token=...) or as
 * a query param (?code=...) depending on the flow. The Supabase JS client
 * resolves this automatically via onAuthStateChange with event "PASSWORD_RECOVERY".
 * We listen for that event to know when the recovery session is active, then
 * allow the user to set a new password.
 */

type PageState = "loading" | "form" | "success" | "invalid";

const ResetPassword = () => {
  const navigate = useNavigate();

  const [pageState, setPageState] = useState<PageState>("loading");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    // If Supabase sent a PKCE code in the URL (?code=...), getSession will
    // exchange it and fire PASSWORD_RECOVERY.  We also listen for
    // SIGNED_IN which Supabase emits on code exchange in newer SDK versions.
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event) => {
      if (event === "PASSWORD_RECOVERY") {
        setPageState("form");
      }
    });

    // Kick off session resolution — handles both hash-based and code-based flows.
    supabase.auth.getSession().then(({ data: { session } }) => {
      // If a session already exists (user is already logged in and followed the
      // link), show the form directly.
      if (session) {
        setPageState("form");
      } else {
        // Give the onAuthStateChange listener 3 seconds to fire before marking
        // the link as invalid.
        const timer = setTimeout(() => {
          setPageState((current) =>
            current === "loading" ? "invalid" : current
          );
        }, 3000);
        return () => clearTimeout(timer);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!password) {
      toast.error("New password is required.");
      return;
    }
    if (password.length < 8) {
      toast.error("Password must be at least 8 characters.");
      return;
    }
    if (password !== confirmPassword) {
      toast.error("Passwords do not match.");
      return;
    }

    setSubmitting(true);

    const { error } = await supabase.auth.updateUser({ password });

    setSubmitting(false);

    if (error) {
      toast.error(error.message ?? "Failed to update password. The link may have expired.");
      return;
    }

    setPageState("success");
    toast.success("Password updated successfully.");

    // Sign out so the user can log in fresh with their new password.
    await supabase.auth.signOut();

    setTimeout(() => navigate("/login", { replace: true }), 2500);
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-4">
      <div className="w-full max-w-sm">
        {/* Logo */}
        <Link to="/" className="mb-10 flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
            <Bot className="h-4 w-4 text-white" />
          </div>
          <span className="text-lg font-bold tracking-tight text-foreground">CROBOT</span>
        </Link>

        {/* Loading */}
        {pageState === "loading" && (
          <div className="flex flex-col items-center gap-4 py-8">
            <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
            <p className="text-sm text-muted-foreground">Verifying reset link…</p>
          </div>
        )}

        {/* Invalid link */}
        {pageState === "invalid" && (
          <div className="space-y-4">
            <h1 className="text-2xl font-bold text-foreground">Link expired</h1>
            <p className="text-sm text-muted-foreground">
              This password reset link is invalid or has expired. Reset links are valid for 1 hour.
            </p>
            <Button
              className="w-full py-5 font-semibold"
              onClick={() => navigate("/forgot-password", { replace: true })}
            >
              Request a new link
            </Button>
          </div>
        )}

        {/* Password form */}
        {pageState === "form" && (
          <div className="space-y-4">
            <div>
              <h1 className="text-2xl font-bold text-foreground">Set new password</h1>
              <p className="mt-1.5 text-sm text-muted-foreground">
                Choose a strong password with at least 8 characters.
              </p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="rp-password">New password</Label>
                <div className="relative">
                  <Input
                    id="rp-password"
                    type={showPassword ? "text" : "password"}
                    placeholder="Enter new password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="border-slate-200 pr-10"
                    required
                    disabled={submitting}
                    autoFocus
                  />
                  <button
                    type="button"
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                    onClick={() => setShowPassword((v) => !v)}
                    aria-label={showPassword ? "Hide password" : "Show password"}
                    tabIndex={-1}
                  >
                    {showPassword ? (
                      <EyeOff className="h-4 w-4" />
                    ) : (
                      <Eye className="h-4 w-4" />
                    )}
                  </button>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="rp-confirm">Confirm new password</Label>
                <div className="relative">
                  <Input
                    id="rp-confirm"
                    type={showConfirm ? "text" : "password"}
                    placeholder="Confirm new password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="border-slate-200 pr-10"
                    required
                    disabled={submitting}
                  />
                  <button
                    type="button"
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                    onClick={() => setShowConfirm((v) => !v)}
                    aria-label={showConfirm ? "Hide confirm password" : "Show confirm password"}
                    tabIndex={-1}
                  >
                    {showConfirm ? (
                      <EyeOff className="h-4 w-4" />
                    ) : (
                      <Eye className="h-4 w-4" />
                    )}
                  </button>
                </div>
              </div>

              {/* Strength indicator */}
              {password.length > 0 && (
                <div className="space-y-1">
                  <div className="flex gap-1">
                    {[1, 2, 3, 4].map((level) => (
                      <div
                        key={level}
                        className={`h-1 flex-1 rounded-full transition-colors ${
                          getStrengthLevel(password) >= level
                            ? getStrengthColor(getStrengthLevel(password))
                            : "bg-slate-200"
                        }`}
                      />
                    ))}
                  </div>
                  <p className="text-xs text-muted-foreground">
                    {getStrengthLabel(getStrengthLevel(password))}
                  </p>
                </div>
              )}

              <Button
                type="submit"
                className="w-full py-5 font-semibold"
                disabled={submitting}
              >
                {submitting ? (
                  <span className="flex items-center gap-2">
                    <span className="h-4 w-4 animate-spin rounded-full border-2 border-primary-foreground border-t-transparent" />
                    Updating…
                  </span>
                ) : (
                  "Update password"
                )}
              </Button>
            </form>
          </div>
        )}

        {/* Success */}
        {pageState === "success" && (
          <div className="space-y-4">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-green-100">
              <svg
                className="h-6 w-6 text-green-600"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
                strokeWidth={2}
              >
                <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <h1 className="text-2xl font-bold text-foreground">Password updated</h1>
            <p className="text-sm text-muted-foreground">
              Your password has been changed successfully. Redirecting you to login…
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

// ── Password strength helpers ───────────────────────────────────

function getStrengthLevel(pw: string): number {
  let score = 0;
  if (pw.length >= 8) score++;
  if (pw.length >= 12) score++;
  if (/[A-Z]/.test(pw) && /[a-z]/.test(pw)) score++;
  if (/\d/.test(pw) && /[^A-Za-z0-9]/.test(pw)) score++;
  return Math.min(score, 4);
}

function getStrengthColor(level: number): string {
  if (level <= 1) return "bg-red-500";
  if (level === 2) return "bg-amber-500";
  if (level === 3) return "bg-yellow-400";
  return "bg-green-500";
}

function getStrengthLabel(level: number): string {
  if (level <= 1) return "Weak password";
  if (level === 2) return "Fair password";
  if (level === 3) return "Good password";
  return "Strong password";
}

export default ResetPassword;

